document.addEventListener('keydown',event=>{const tab=event.target.closest?.('[role="tab"][data-detail]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const views=['overview','details','analysis'],index=views.indexOf(state.riskDetail);state.riskDetail=event.key==='Home'?'overview':event.key==='End'?'analysis':views[(index+(event.key==='ArrowRight'?1:2))%3];persist();render();$('#risk-tab-'+state.riskDetail)?.focus?.();});
document.addEventListener('dragstart',event=>{const row=event.target.closest('[data-nav-route]');if(!row?.dataset.navRoute||!event.dataTransfer)return;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('application/x-investsight-navigation',row.dataset.navRoute);row.classList.add('is-dragging');});
document.addEventListener('dragover',event=>{const target=event.target.closest('[data-nav-group]');if(!target?.dataset.navGroup||!event.dataTransfer||!Array.from(event.dataTransfer.types||[]).includes('application/x-investsight-navigation'))return;event.preventDefault();event.dataTransfer.dropEffect='move';target.classList.add('nav-drag-over');});
document.addEventListener('dragleave',event=>{const target=event.target.closest('[data-nav-group]');if(target?.dataset.navGroup&&!target.contains(event.relatedTarget))target.classList.remove('nav-drag-over');});
document.addEventListener('drop',event=>{const target=event.target.closest('[data-nav-group]');if(!target?.dataset.navGroup||!event.dataTransfer)return;const route=event.dataTransfer.getData('application/x-investsight-navigation');if(!route)return;event.preventDefault();const before=target.dataset.navRoute||null;if(placeNavigation(route,target.dataset.navGroup,before)){render();toast('Sidebar arrangement saved.');}$$('.nav-drag-over,.is-dragging').forEach(el=>el.classList.remove('nav-drag-over','is-dragging'));});
document.addEventListener('dragend',()=>$$('.nav-drag-over').forEach(el=>el.classList.remove('nav-drag-over')));

document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||!state.signedIn)return;const events={'select-stock':['Research','Stock selected'],'remove-selection':['Research','Stock selection removed'],watch:['Research','Watchlist updated'],'toggle-pause':['Execution','Entry pause changed'],'confirm-cancel':['Orders','Remaining quantity cancelled'],'confirm-revoke':['Execution','Agreement revoked'],'mark-read':['Preferences','Notifications marked read'],'create-report':['Reports','Report generated']};const entry=events[b.dataset.action];if(entry)recordAudit(entry[0],entry[1],strategy().name+(b.dataset.id?' · '+b.dataset.id:''));});
document.addEventListener('submit',event=>{const f=event.target;if(!f.matches('form')||!state.signedIn)return;const events={broker:['Account','Broker permissions saved'],budget:['Execution','Strategy budget reviewed'],agreement:['Execution','Agreement reviewed'],alert:['Alerts','Company alert saved'],profile:['Preferences','Profile updated'],notifications:['Preferences','Notification preference saved'],report:['Reports','Report generated']};const entry=events[f.dataset.form];if(entry)recordAudit(entry[0],entry[1],strategy().name+' · '+broker().name);});

render();

document.addEventListener('change',event=>{if(event.target.id==='model-company'&&stockData.some(company=>company.id===event.target.value)){modelFocusByStrategy[state.strategy]=event.target.value;const y=scrollY;render();window.scrollTo(0,y);$('#model-company')?.focus?.({preventScroll:true});}});
